void CChatSlider::SetState(int state)
{
    int n = numStates;
    if (state >= n)
        state = n - 1;
    if (state < 0)
        state = 0;
    currentState = state;
    oldState = state;
    if (n <= 1)
        knobPos = 0x10;
    else
        knobPos = knobRange * state / (n - 1) + 0x10;
}

